/**
 * API response types, derived from the committed OpenAPI document.
 *
 * `schema.d.ts` is generated by `pnpm gen:api`; this module gives the rest of the app short,
 * stable names for the schemas it consumes so components never reach into the generated
 * `components["schemas"]` path directly.
 */

import type { components } from "./schema";

export type PublicUser = components["schemas"]["PublicUser"];
export type LoginRequest = components["schemas"]["LoginRequest"];
export type SignupRequest = components["schemas"]["SignupRequest"];
export type LogoutResponse = components["schemas"]["LogoutResponse"];

export type LeagueSummary = components["schemas"]["LeagueSummary"];
export type AddLeagueRequest = components["schemas"]["AddLeagueRequest"];
export type AddLeagueResponse = components["schemas"]["AddLeagueResponse"];

export type OwnerSummary = components["schemas"]["OwnerSummary"];
export type OwnersResponse = components["schemas"]["OwnersResponse"];
export type OwnerUpdateRequest = components["schemas"]["OwnerUpdateRequest"];
export type OwnerUpdateResponse = components["schemas"]["OwnerUpdateResponse"];

export type SeasonsResponse = components["schemas"]["SeasonsResponse"];
export type RefreshResponse = components["schemas"]["RefreshResponse"];

export type StandingsRow = components["schemas"]["StandingsRow"];
export type DivisionStandings = components["schemas"]["DivisionStandings"];
export type StandingsResponse = components["schemas"]["StandingsResponse"];
export type TeamVpHistory = components["schemas"]["TeamVpHistory"];
export type VpHistoryResponse = components["schemas"]["VpHistoryResponse"];
